#include "k5-int.h"

#include "gssapiP_krb5.h"



#ifndef MIN             /* Usually found in <sys/param.h>. */

#define MIN(_a,_b)  ((_a)<(_b)?(_a):(_b))

#endif



OM_uint32 KRB5_CALLCONV

krb5_gss_pseudo_random(OM_uint32 *minor_status,

                       gss_ctx_id_t context,

                       int prf_key,

                       const gss_buffer_t prf_in,

                       ssize_t desired_output_len,

                       gss_buffer_t prf_out)

{

    krb5_error_code code;

    krb5_key key = NULL;

    krb5_gss_ctx_id_t ctx;

    int i;

    OM_uint32 minor;

    size_t prflen;

    krb5_data t, ns;

    unsigned char *p;



    prf_out->length = 0;

    prf_out->value = NULL;



    t.length = 0;

    t.data = NULL;



    ns.length = 0;

    ns.data = NULL;



    ctx = (krb5_gss_ctx_id_t)context;



    switch (prf_key) {

    case GSS_C_PRF_KEY_FULL:

        if (ctx->have_acceptor_subkey) {

            key = ctx->acceptor_subkey;

            break;

        }

        /* fallthrough */

    case GSS_C_PRF_KEY_PARTIAL:

        key = ctx->subkey;

        break;

    default:

        code = EINVAL;

        goto cleanup;

    }



    if (key == NULL) {

        code = EINVAL;

        goto cleanup;

    }



    if (desired_output_len == 0)

        return GSS_S_COMPLETE;



    prf_out->value = k5alloc(desired_output_len, &code);

    if (prf_out->value == NULL) {

        code = KG_INPUT_TOO_LONG;

        goto cleanup;

    }

    prf_out->length = desired_output_len;



    code = krb5_c_prf_length(ctx->k5_context,

                             krb5_k_key_enctype(ctx->k5_context, key),

                             &prflen);

    if (code != 0)

        goto cleanup;



    ns.length = 4 + prf_in->length;

    ns.data = k5alloc(ns.length, &code);

    if (ns.data == NULL) {

        code = KG_INPUT_TOO_LONG;

        goto cleanup;

    }



    t.length = prflen;

    t.data = k5alloc(t.length, &code);

    if (t.data == NULL)

        goto cleanup;



    memcpy(ns.data + 4, prf_in->value, prf_in->length);

    i = 0;

    p = (unsigned char *)prf_out->value;

    while (desired_output_len > 0) {

        store_32_be(i, ns.data);



        code = krb5_k_prf(ctx->k5_context, key, &ns, &t);

        if (code != 0)

            goto cleanup;



        memcpy(p, t.data, MIN(t.length, desired_output_len));



        p += t.length;

        desired_output_len -= t.length;

        i++;

    }



cleanup:

    if (code != 0)

        gss_release_buffer(&minor, prf_out);

    krb5_free_data_contents(ctx->k5_context, &ns);

    krb5_free_data_contents(ctx->k5_context, &t);



    *minor_status = (OM_uint32)code;

    return (code == 0) ? GSS_S_COMPLETE : GSS_S_FAILURE;

}

#ifdef HAVE_LIBWEBP

#include <stdio.h>

#include <math.h>

#include <string.h>

#include <stdlib.h>

#include "gd.h"

#include "gdhelpers.h"

#include "webp/decode.h"

#include "webp/encode.h"



#define GD_WEBP_ALLOC_STEP (4*1024)



gdImagePtr gdImageCreateFromWebp (FILE * inFile)

{

	gdImagePtr im;

	gdIOCtx *in = gdNewFileCtx(inFile);

	if (!in)

		return 0;

	im = gdImageCreateFromWebpCtx(in);

	in->gd_free(in);



	return im;

}





gdImagePtr gdImageCreateFromWebpPtr (int size, void *data)

{

	gdImagePtr im;

	gdIOCtx *in = gdNewDynamicCtxEx(size, data, 0);

	if (!in)

		return 0;

	im = gdImageCreateFromWebpCtx(in);

	in->gd_free(in);

	return im;

}



gdImagePtr gdImageCreateFromWebpCtx (gdIOCtx * infile)

{

	int    width, height;

	uint8_t   *filedata = NULL;

	uint8_t    *argb = NULL;

	size_t size = 0, n;

	gdImagePtr im;

	int x, y;

	uint8_t *p;



	do {

		unsigned char *read, *temp;



		temp = gdRealloc(filedata, size+GD_WEBP_ALLOC_STEP);

		if (temp) {

			filedata = temp;

			read = temp + size;

		} else {

			if (filedata) {

				gdFree(filedata);

			}

			zend_error(E_ERROR, "WebP decode: realloc failed");

			return NULL;

		}



		n = gdGetBuf(read, GD_WEBP_ALLOC_STEP, infile);

		if (n>0 && n!=EOF) {

			size += n;

		}

	} while (n>0 && n!=EOF);



	if (WebPGetInfo(filedata,size, &width, &height) == 0) {

		zend_error(E_ERROR, "gd-webp cannot get webp info");

		gdFree(filedata);

		return NULL;

	}



	im = gdImageCreateTrueColor(width, height);

	if (!im) {

		gdFree(filedata);

		return NULL;

	}

	argb = WebPDecodeARGB(filedata, size, &width, &height);

	if (!argb) {

		zend_error(E_ERROR, "gd-webp cannot allocate temporary buffer");

		gdFree(filedata);

		gdImageDestroy(im);

		return NULL;

	}

	for (y = 0, p = argb;  y < height; y++) {

		for (x = 0; x < width; x++) {

			register uint8_t a = gdAlphaMax - (*(p++) >> 1);

			register uint8_t r = *(p++);

			register uint8_t g = *(p++);

			register uint8_t b = *(p++);

			im->tpixels[y][x] = gdTrueColorAlpha(r, g, b, a);

		}

	}

	gdFree(filedata);

	/* do not use gdFree here, in case gdFree/alloc is mapped to something else than libc */

	free(argb);

	im->saveAlphaFlag = 1;

	return im;

}



void gdImageWebpCtx (gdImagePtr im, gdIOCtx * outfile, int quantization)

{

	uint8_t *argb;

	int x, y;

	uint8_t *p;

	uint8_t *out;

	size_t out_size;



	if (im == NULL) {

		return;

	}



	if (!gdImageTrueColor(im)) {

		zend_error(E_ERROR, "Paletter image not supported by webp");

		return;

	}



	if (quantization == -1) {

		quantization = 80;

	}



	argb = (uint8_t *)gdMalloc(gdImageSX(im) * 4 * gdImageSY(im));

	if (!argb) {

		return;

	}

	p = argb;

	for (y = 0; y < gdImageSY(im); y++) {

		for (x = 0; x < gdImageSX(im); x++) {

			register int c;

			register char a;

			c = im->tpixels[y][x];

			a = gdTrueColorGetAlpha(c);

			if (a == 127) {

				a = 0;

			} else {

				a = 255 - ((a << 1) + (a >> 6));

			}

			*(p++) = gdTrueColorGetRed(c);

			*(p++) = gdTrueColorGetGreen(c);

			*(p++) = gdTrueColorGetBlue(c); 

			*(p++) = a;

		}

	}

	out_size = WebPEncodeRGBA(argb, gdImageSX(im), gdImageSY(im), gdImageSX(im) * 4, quantization, &out);

	if (out_size == 0) {

		zend_error(E_ERROR, "gd-webp encoding failed");

		goto freeargb;

	}

	gdPutBuf(out, out_size, outfile);

	free(out);



freeargb:

	gdFree(argb);

}



void gdImageWebpEx (gdImagePtr im, FILE * outFile, int quantization)

{

	gdIOCtx *out = gdNewFileCtx(outFile);

	gdImageWebpCtx(im, out, quantization);

	out->gd_free(out);

}



void gdImageWebp (gdImagePtr im, FILE * outFile)

{

	gdIOCtx *out = gdNewFileCtx(outFile);

	gdImageWebpCtx(im, out, -1);

	out->gd_free(out);

}



void * gdImageWebpPtr (gdImagePtr im, int *size)

{

	void *rv;

	gdIOCtx *out = gdNewDynamicCtx(2048, NULL);

	gdImageWebpCtx(im, out, -1);

	rv = gdDPExtractData(out, size);

	out->gd_free(out);



	return rv;

}



void * gdImageWebpPtrEx (gdImagePtr im, int *size, int quantization)

{

	void *rv;

	gdIOCtx *out = gdNewDynamicCtx(2048, NULL);

	gdImageWebpCtx(im, out, quantization);

	rv = gdDPExtractData(out, size);

	out->gd_free(out);

	return rv;

}

